/// Return `N` bytes (little-endian) generated by a SplitMix generator seeded with `seed`.
///
/// The reference implementations suggest to fill the state, carry included,
/// with the output of SplitMix.
pub(crate) fn splitmix_bytes<const N: usize>(mut seed: u64) -> [u8; N] {
    let mut out = [0; N];
    for chunk in out.chunks_mut(8) {
        seed = seed.wrapping_add(0x9e3779b97f4a7c15);
        let mut z = seed;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d049bb133111eb);
        z ^= z >> 31;
        chunk.copy_from_slice(&z.to_le_bytes()[..chunk.len()]);
    }
    out
}

/// Return the little-endian bytes of the integer held in `words`.
pub(crate) fn to_bytes<const N: usize, const B: usize>(words: [u64; N]) -> [u8; B] {
    const { assert!(B == 8 * N) };
    let mut out = [0; B];
    for (chunk, w) in out.chunks_exact_mut(8).zip(words) {
        chunk.copy_from_slice(&w.to_le_bytes());
    }
    out
}

/// A source of random bytes all equal to the given value, for testing.
#[cfg(test)]
pub(crate) struct ConstRng(pub u8);

#[cfg(test)]
impl rand_core::TryRng for ConstRng {
    type Error = core::convert::Infallible;

    fn try_next_u32(&mut self) -> Result<u32, Self::Error> {
        Ok(u32::from_ne_bytes([self.0; 4]))
    }

    fn try_next_u64(&mut self) -> Result<u64, Self::Error> {
        Ok(u64::from_ne_bytes([self.0; 8]))
    }

    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), Self::Error> {
        dest.fill(self.0);
        Ok(())
    }
}
